          "expect": "fe80=[true,true] global=[false,true]"
        },
        {
          "claim": "The same flip happens when the zoned address is one element of a longer host list.",
          "probe": "const c={hosts:['96.87.107.24','a644::8654%eth0']};\nprint('o='+oracle.parseConfig(c).ok+' m='+main.parseConfig(c).ok);",
          "expect": "o=false m=true"
        }
      ]
    },
    {
      "heading": "[463] config: timeoutMs was ACCEPTED, now REJECTED",
      "answers": {
        "verdict_changes": true,
        "direction": "stricter",
        "stored_value_changes": false,
        "already_signed_off": false,
